ValidationRule.errorConditionFormula:
AND(
  /* only if the app filled your single geolocation field */
  NOT( ISBLANK( Check_In_Location__Latitude__s ) ),
  NOT( ISBLANK( Check_In_Location__Longitude__s ) ),

  /* Haversine formula in kilometres; Earth ≈ 6371 km */
  (
    6371 *
    ACOS(
      COS( Account__r.Account_Location__Latitude__s  * 0.0174532925199433 ) *
      COS( Check_In_Location__Latitude__s             * 0.0174532925199433 ) *
      COS(
        ( Check_In_Location__Longitude__s -
          Account__r.Account_Location__Longitude__s 
        )                                          * 0.0174532925199433
      ) +
      SIN( Account__r.Account_Location__Latitude__s  * 0.0174532925199433 ) *
      SIN( Check_In_Location__Latitude__s             * 0.0174532925199433 )
    )
  ) > 0.3  /* 0.3 km = 300 m; adjust as needed */
)
